/* Differential-test wrapper for the drafts src/drafts/wwlib/saveload_ids.rs and saveloadstatus.rs (#215, group wwlib2),
** upstream commit 0a05454d:
**   WWSaveLoad/saveloadids.h and WWMath/wwmathids.h (the chunk id enums), #included UNCHANGED;
**   WWSaveLoad/saveloadstatus.h and saveloadstatus.cpp, #included UNCHANGED.
** wwdebug.h is the release-build shim of differential/shim (WWASSERT compiled out, as in the shipped game).
** Stand-ins (generated by build.rs drafts_wwlib2 into OUT_DIR/draft_wwlib2_standin, which only this translation unit sees):
**   wwstring.h: StringClass reduced to what saveloadstatus.cpp uses (assignment from `const char *` and from another
**   StringClass, conversion to `const char *`); mutex.h: CriticalSectionClass with a LockClass that does nothing (the test
**   is single-threaded).
**
** Entry points: ref_sl_ids(out) writes the 26 constants in the order of the test's table. ref_sl_status(prog, n, out): `prog`
** words: 0 id t = Set_Status_Text(texts[t], id) (texts: "", "a", "hello world", "sub"); 1 id = Get_Status_Text (appends length, then the
** characters); 2 = Reset_Status_Count; 3 = Inc_Status_Count; 4 = Get_Status_Count (appends the count). Returns the words written. */
#include <stddef.h>
#include <string.h>
#include "wwdebug.h"
#include "../upstream/GeneralsMD/Code/Libraries/Source/WWVegas/WWSaveLoad/saveloadids.h"
#include "../upstream/GeneralsMD/Code/Libraries/Source/WWVegas/WWMath/wwmathids.h"
#include "../upstream/GeneralsMD/Code/Libraries/Source/WWVegas/WWSaveLoad/saveloadstatus.cpp"

extern "C" {

void ref_sl_ids(unsigned *out)
{
	unsigned v[] = {
		CHUNKID_SAVELOAD_BEGIN, CHUNKID_SAVELOAD_DEFMGR, CHUNKID_TWIDDLER, CHUNKID_WW3D_BEGIN, CHUNKID_WWPHYS_BEGIN,
		CHUNKID_WWAUDIO_BEGIN, CHUNKID_COMBAT_BEGIN, CHUNKID_COMMANDO_EDITOR_BEGIN, CHUNKID_PHYSTEST_BEGIN, CHUNKID_COMMANDO_BEGIN,
		CHUNKID_WWMATH_BEGIN, CHUNKID_WWTRANSLATEDB_BEGIN,
		WWMATH_CHUNKID_LINEARCURVE1D, WWMATH_CHUNKID_HERMITESPLINE1D, WWMATH_CHUNKID_CATMULLROMSPLINE1D, WWMATH_CHUNKID_CARDINALSPLINE1D,
		WWMATH_CHUNKID_TCBSPLINE1D, WWMATH_CHUNKID_LINEARCURVE3D, WWMATH_CHUNKID_HERMITESPLINE3D, WWMATH_CHUNKID_CATMULLROMSPLINE3D,
		WWMATH_CHUNKID_CARDINALSPLINE3D, WWMATH_CHUNKID_TCBSPLINE3D, WWMATH_CHUNKID_VEHICLECURVE,
	};
	for (unsigned i = 0; i < sizeof(v) / sizeof(v[0]); i++) out[i] = v[i];
}

int ref_sl_status(const unsigned *prog, int n, unsigned *out)
{
	static const char *texts[4] = {"", "a", "hello world", "sub"};
	int w = 0;
	for (int i = 0; i < n;) {
		switch (prog[i]) {
		case 0: SaveLoadStatus::Set_Status_Text(texts[prog[i + 2]], (int)prog[i + 1]); i += 3; break;
		case 1: {
			StringClass s;
			SaveLoadStatus::Get_Status_Text(s, (int)prog[i + 1]);
			const char *c = (const char *)s;
			out[w++] = (unsigned)strlen(c);
			for (size_t k = 0; k < strlen(c); k++) out[w++] = (unsigned char)c[k];
			i += 2;
			break;
		}
		case 2: SaveLoadStatus::Reset_Status_Count(); i += 1; break;
		case 3: SaveLoadStatus::Inc_Status_Count(); i += 1; break;
		default: out[w++] = (unsigned)SaveLoadStatus::Get_Status_Count(); i += 1; break;
		}
	}
	return w;
}

}
